Future<void> _restoreSavedTrip() async {
  try {
    final store = await openTripStore();
    _tripStore = store;
    final saved = await store.load();
    if (!mounted || saved == null) return;
    if (!saved.recorder.running) {
      _applySavedTrip(saved, tracking: false);
      return;
    }
    final choice = await showDialog<TripRecoveryChoice>(
      context: context,
      barrierDismissible: false,
      builder: (_) => TripRecoveryDialog(
        summary: saved.recorder.snapshot(saved.savedAt), partial: saved.partial),
    );
    if (!mounted) return;
    if (choice == TripRecoveryChoice.discard) {
      await _persistTrip((store) => store.discard());
      return;
    }
    if (choice == TripRecoveryChoice.resume) {
      final now = DateTime.now();
      await _persistTrip((store) => store.resume(saved, now));
      if (!mounted) return;
      saved.recorder.resumeAfterInterruption();
      _applySavedTrip(saved, tracking: true);
      _startTripTimer();
    } else if (choice == TripRecoveryChoice.finish) {
      // Ending at the last saved clock avoids treating hours with the app
      // closed as measured travel or changing an already completed average.
      saved.recorder.stop(saved.savedAt);
      await _persistTrip((store) => store.finishRecovered(saved));
      if (!mounted) return;
      _applySavedTrip(saved, tracking: false);
      await _showTripSummary();
    }
  } catch (error, stack) {
    _tripSaveError(error, stack);
  } finally {
    if (mounted) setState(() { _restoringTrip = false; });
  }
}

