    _activeLegIndex = saved.activeLeg;
    _destinationReached = saved.arrived;
    _trackingTrip = tracking;
    _lastTripSummary = tracking ? null : _tripRecorder.snapshot(saved.savedAt);
    _lastTripCheckpoint = DateTime.now();
    if (tracking) _locationStatus = 'Waiting for fresh GPS • saved trip restored';
  });
  unawaited(_refreshMapData());
  unawaited(_refreshCurrentMarker());
}

